public class NullSafeSortTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String sorted(String... values) {
        java.util.List<String> list = new java.util.ArrayList<>(java.util.Arrays.asList(values));
        try {
            NullSafeSort.sortNullsFirst(list);
            return list.toString();
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("nulls in the middle move to the front",
                "[null, null, apple, banana, pear]",
                sorted("pear", null, "apple", null, "banana"));
        check("single null mid-list",
                "[null, ant, bee]",
                sorted("bee", null, "ant"));
        check("no nulls -- plain alphabetical sort",
                "[cherry, fig, plum]",
                sorted("plum", "cherry", "fig"));
        check("all nulls stay put",
                "[null, null, null]",
                sorted(null, null, null));
        check("duplicates kept",
                "[null, kiwi, kiwi, lime]",
                sorted("kiwi", "lime", null, "kiwi"));
        check("empty list is fine", "[]", sorted());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

